import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class Main {
    record Expense(String category, BigDecimal amount) { }
    public static void main(String[] args) throws Exception {
        List<Expense> expenses = List.of(
            new Expense("Food", new BigDecimal("125.50")),
            new Expense("Travel", new BigDecimal("40.00")),
            new Expense("Food", new BigDecimal("25.25")));
        BigDecimal total = expenses.stream().map(Expense::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
        String csv = "category,amount\n" + expenses.stream().map(e -> e.category() + "," + e.amount()).reduce((a,b) -> a + "\n" + b).orElse("") + "\nTOTAL," + total + "\n";
        Path output = Path.of("expense-report.csv");
        Files.writeString(output, csv);
        System.out.println("Total: " + total + "; written to " + output.toAbsolutePath());
    }
}
